/* Inspire Talent Hub — Premium authored question bank (DEEP EXPANSION, batch 1)
 * Chapter: Chemical Reactions and Equations (CBSE Class 10 Science).
 *
 * This file MERGES additional educator-grade questions into the existing chapter
 * bank so a chapter can grow across batches without rewriting the base file.
 * Loaded AFTER qbank-science-10.js. The exam engine shuffles and samples from the
 * whole pool, so a larger bank yields far more unique papers automatically.
 */
(function () {
  var Q = window.ITH_QBANK = window.ITH_QBANK || {};
  var b = Q['cbse|10|science|chemical-reactions-and-equations'];
  if (!b) return;
  function add(key, arr) { (b[key] = b[key] || []).push.apply(b[key], arr); }

  add('mcq', [
    { q: 'A change in which one or more new substances with new properties are formed is called:', o: ['A chemical change', 'A physical change', 'A change of state only', 'A reversible physical change'], a: 0, d: 1, e: 'New substances with new properties indicate a chemical change.' },
    { q: 'Which of the following is NOT a sign that a chemical reaction has occurred?', o: ['A change in shape with no new substance', 'Evolution of a gas', 'A change in colour', 'Formation of a precipitate'], a: 0, d: 2, e: 'A mere change of shape (no new substance) is a physical change.' },
    { q: 'The symbol “↑” written after a product in a chemical equation shows that it is:', o: ['A gas evolved', 'A precipitate', 'A catalyst', 'Heat supplied'], a: 0, d: 1, e: '↑ indicates a gas is given off.' },
    { q: 'The symbol “↓” written after a product in a chemical equation shows that it is:', o: ['An insoluble precipitate', 'A gas evolved', 'A reversible reaction', 'Water added'], a: 0, d: 1, e: '↓ indicates an insoluble solid (precipitate).' },
    { q: 'In a chemical equation, a substance dissolved in water is shown by the state symbol:', o: ['(aq)', '(s)', '(l)', '(g)'], a: 0, d: 1, e: '(aq) = aqueous (dissolved in water).' },
    { q: 'The balanced equation for “zinc + sulphuric acid → zinc sulphate + hydrogen” is:', o: ['Zn + H₂SO₄ → ZnSO₄ + H₂', 'Zn + 2H₂SO₄ → ZnSO₄ + 2H₂', '2Zn + H₂SO₄ → 2ZnSO₄ + H₂', 'Zn + H₂SO₄ → ZnS + O₂ + H₂'], a: 0, d: 2, e: 'Atoms already balance one-to-one.' },
    { q: 'The correct balanced equation for the burning of hydrogen is:', o: ['2H₂ + O₂ → 2H₂O', 'H₂ + O₂ → H₂O', 'H₂ + O₂ → 2H₂O', '2H₂ + 2O₂ → 2H₂O'], a: 0, d: 2, e: '4 H and 2 O on each side.' },
    { q: 'The number of oxygen atoms on each side of C + O₂ → CO₂ is:', o: ['2', '1', '3', '4'], a: 0, d: 1, e: 'O₂ has 2 O; CO₂ has 2 O.' },
    { q: 'The burning of coal, C + O₂ → CO₂, is an example of a:', o: ['Combination reaction', 'Decomposition reaction', 'Displacement reaction', 'Double displacement reaction'], a: 0, d: 1, e: 'Two substances combine into one product.' },
    { q: 'The reaction 2H₂O →(electricity) 2H₂ + O₂ is a:', o: ['Electrolytic decomposition', 'Thermal decomposition', 'Photochemical decomposition', 'Combination reaction'], a: 0, d: 2, e: 'Electricity breaks water into its elements.' },
    { q: 'On strong heating, calcium carbonate decomposes into calcium oxide and:', o: ['Carbon dioxide', 'Oxygen', 'Carbon monoxide', 'Water'], a: 0, d: 1, e: 'CaCO₃ → CaO + CO₂.' },
    { q: 'The decomposition of silver bromide in sunlight is used in:', o: ['Photography', 'Welding', 'Electroplating', 'Fire extinguishers'], a: 0, d: 2, e: 'Light-sensitive AgBr is used in black-and-white photography.' },
    { q: 'Which of the following is a double displacement reaction?', o: ['Na₂SO₄ + BaCl₂ → BaSO₄ + 2NaCl', 'Fe + CuSO₄ → FeSO₄ + Cu', '2Pb(NO₃)₂ → 2PbO + 4NO₂ + O₂', 'C + O₂ → CO₂'], a: 0, d: 2, e: 'Ions are exchanged, forming a precipitate.' },
    { q: 'When silver nitrate solution is added to sodium chloride solution, the white precipitate is:', o: ['Silver chloride', 'Sodium nitrate', 'Silver oxide', 'Sodium silver'], a: 0, d: 2, e: 'AgNO₃ + NaCl → AgCl↓ + NaNO₃.' },
    { q: 'The yellow precipitate formed when potassium iodide is added to lead nitrate solution is:', o: ['Lead iodide', 'Potassium nitrate', 'Lead nitrate', 'Iodine'], a: 0, d: 2, e: 'Pb(NO₃)₂ + 2KI → PbI₂↓ (yellow) + 2KNO₃.' },
    { q: 'In the reaction ZnO + C → Zn + CO, carbon acts as a:', o: ['Reducing agent', 'Oxidising agent', 'Catalyst', 'Acid'], a: 0, d: 3, comp: true, e: 'Carbon removes oxygen from ZnO, so it is the reducing agent.' },
    { q: 'In MnO₂ + 4HCl → MnCl₂ + 2H₂O + Cl₂, the substance oxidised is:', o: ['HCl (chloride → chlorine)', 'MnO₂', 'H₂O', 'MnCl₂'], a: 0, d: 3, comp: true, e: 'Cl goes from −1 to 0 (oxidised); Mn is reduced.' },
    { q: 'The rusting of iron is a slow:', o: ['Oxidation reaction', 'Reduction reaction', 'Neutralisation reaction', 'Decomposition reaction'], a: 0, d: 2, e: 'Iron is oxidised by air and moisture.' },
    { q: 'The black coating that forms on silver articles over time is:', o: ['Silver sulphide', 'Silver oxide', 'Silver chloride', 'Silver carbonate'], a: 0, d: 2, e: 'Silver reacts with H₂S to form black Ag₂S.' },
    { q: 'The green coating on copper vessels in moist air is basic copper:', o: ['Carbonate', 'Chloride', 'Sulphide', 'Oxide'], a: 0, d: 2, e: 'Copper forms green basic copper carbonate.' },
    { q: 'Rancidity of fried food in a sealed packet is prevented by flushing it with:', o: ['Nitrogen', 'Oxygen', 'Carbon dioxide', 'Hydrogen'], a: 0, d: 2, e: 'Unreactive nitrogen keeps oxygen away from the fats.' },
    { q: 'Substances added to fatty foods to slow down their oxidation are called:', o: ['Antioxidants', 'Preservatives (acids)', 'Catalysts', 'Indicators'], a: 0, d: 2, e: 'Antioxidants prevent rancidity.' },
    { q: 'Which of the following is an endothermic process?', o: ['Decomposition of calcium carbonate on heating', 'Respiration', 'Burning of natural gas', 'Reaction of quicklime with water'], a: 0, d: 2, e: 'Decomposition of CaCO₃ absorbs heat.' },
    { q: 'The reaction of quicklime with water is:', o: ['Exothermic', 'Endothermic', 'Neutralisation', 'Photochemical'], a: 0, d: 1, e: 'It releases a large amount of heat.' },
    { q: 'Which pair correctly matches a reaction with its type?', o: ['CaO + H₂O → Ca(OH)₂ : combination', '2H₂O → 2H₂ + O₂ : combination', 'Fe + CuSO₄ → FeSO₄ + Cu : decomposition', '2AgCl → 2Ag + Cl₂ : displacement'], a: 0, d: 3, comp: true, e: 'CaO + H₂O forming one product is combination.' },
    { q: 'The brown gas evolved when lead nitrate is heated is:', o: ['Nitrogen dioxide', 'Oxygen', 'Nitrogen', 'Ammonia'], a: 0, d: 2, e: '2Pb(NO₃)₂ → 2PbO + 4NO₂ + O₂; NO₂ is brown.' },
    { q: 'When ferrous sulphate crystals are heated strongly, the smell produced resembles that of burning:', o: ['Sulphur', 'Wood', 'Coal', 'Plastic'], a: 0, d: 2, e: 'SO₂ and SO₃ are released, smelling of burning sulphur.' },
    { q: 'The blue colour of copper sulphate solution changes to light green when the metal added is:', o: ['Iron', 'Copper', 'Silver', 'Gold'], a: 0, d: 2, e: 'Iron displaces copper, forming green FeSO₄.' },
    { q: 'Which metal will NOT displace copper from copper sulphate solution?', o: ['Silver', 'Iron', 'Zinc', 'Aluminium'], a: 0, d: 2, comp: true, e: 'Silver is less reactive than copper.' },
    { q: 'The digestion of food in our body is chemically a:', o: ['Decomposition reaction', 'Combination reaction', 'Displacement reaction', 'Neutralisation reaction'], a: 0, d: 2, e: 'Large molecules break into simpler ones.' },
    { q: 'The reaction H₂ + Cl₂ → 2HCl is a:', o: ['Combination reaction', 'Decomposition reaction', 'Displacement reaction', 'Double displacement reaction'], a: 0, d: 2, e: 'Two elements combine into one compound.' },
    { q: 'Which of the following equations is correctly balanced?', o: ['2Al + 3CuCl₂ → 2AlCl₃ + 3Cu', 'Al + CuCl₂ → AlCl₃ + Cu', '2Al + CuCl₂ → 2AlCl₃ + Cu', 'Al + 3CuCl₂ → AlCl₃ + 3Cu'], a: 0, d: 3, comp: true, e: '2 Al, 3 Cu, 6 Cl on each side.' },
    { q: 'The precipitate of barium sulphate formed when barium chloride reacts with sodium sulphate is:', o: ['White', 'Yellow', 'Green', 'Black'], a: 0, d: 2, e: 'BaSO₄ is a white precipitate.' },
    { q: 'A reaction in which heat is given out to the surroundings is called:', o: ['Exothermic', 'Endothermic', 'Photolytic', 'Reversible'], a: 0, d: 1, e: 'Heat released → exothermic.' },
    { q: 'Heat is released when vegetable matter decomposes into compost, showing the process is:', o: ['Exothermic', 'Endothermic', 'Neutralisation', 'Reversible'], a: 0, d: 2, e: 'Release of heat means exothermic.' },
    { q: 'In the reaction 2Mg + O₂ → 2MgO, the substance oxidised is:', o: ['Magnesium', 'Oxygen', 'Magnesium oxide', 'None of these'], a: 0, d: 2, e: 'Mg gains oxygen, so Mg is oxidised.' },
    { q: 'The substance that supplies oxygen to (or removes hydrogen from) another substance in a redox reaction is the:', o: ['Oxidising agent', 'Reducing agent', 'Catalyst', 'Solvent'], a: 0, d: 2, e: 'It oxidises the other substance.' },
    { q: 'Which of the following metals reacts with dilute hydrochloric acid to give hydrogen gas?', o: ['Zinc', 'Copper', 'Silver', 'Gold'], a: 0, d: 2, e: 'Zn is above H in the reactivity series.' },
    { q: 'A shiny brown element X, on heating in air, becomes a black substance. X and the black substance are:', o: ['Copper and copper(II) oxide', 'Iron and iron oxide', 'Silver and silver oxide', 'Zinc and zinc oxide'], a: 0, d: 2, comp: true, e: '2Cu + O₂ → 2CuO (black).' },
    { q: 'The black copper(II) oxide formed on heating copper can be changed back to brown copper by passing over it:', o: ['Hydrogen gas', 'Oxygen', 'Carbon dioxide', 'Steam'], a: 0, d: 3, comp: true, e: 'CuO + H₂ → Cu + H₂O.' },
    { q: 'Which of the following is a combination reaction that gives out heat and light?', o: ['Burning of a magnesium ribbon', 'Electrolysis of water', 'Rusting of iron', 'Digestion of food'], a: 0, d: 2, e: 'Mg burns with a dazzling white flame.' },
    { q: 'Rust is chemically represented as:', o: ['Fe₂O₃·xH₂O', 'FeO', 'Fe₃O₄', 'FeCl₃'], a: 0, d: 2, e: 'Rust is hydrated iron(III) oxide.' },
    { q: 'The reaction Zn + CuSO₄ → ZnSO₄ + Cu is a displacement reaction and also a:', o: ['Redox reaction', 'Combination reaction', 'Neutralisation reaction', 'Decomposition reaction'], a: 0, d: 3, comp: true, e: 'Zn is oxidised and Cu²⁺ is reduced.' },
    { q: 'While balancing a chemical equation, we are allowed to change only the:', o: ['Coefficients (numbers before formulae)', 'Subscripts in a formula', 'Symbols of the elements', 'Products of the reaction'], a: 0, d: 2, e: 'Changing subscripts would change the substance.' },
    { q: 'The reaction between an acid and a base to form salt and water is a special type of:', o: ['Double displacement reaction', 'Combination reaction', 'Decomposition reaction', 'Displacement reaction'], a: 0, d: 2, e: 'Neutralisation is a double displacement (ion-exchange) reaction.' }
  ]);

  add('ar', [
    { A: 'The burning of magnesium is a combination reaction.', R: 'Magnesium combines with oxygen to form a single product, magnesium oxide.', a: 0 },
    { A: 'Both respiration and combustion are exothermic reactions.', R: 'Respiration takes place inside the living cells of the body.', a: 1 },
    { A: 'A displacement reaction occurs when an iron nail is dipped in copper sulphate solution.', R: 'Copper is more reactive than iron.', a: 2 },
    { A: 'Silver is more reactive than copper.', R: 'A more reactive metal displaces a less reactive metal from its salt solution.', a: 3 },
    { A: 'An unbalanced chemical equation does not obey the law of conservation of mass.', R: 'A balanced equation has an equal number of atoms of each element on both sides.', a: 0 },
    { A: 'The decomposition of calcium carbonate requires continuous heating.', R: 'The decomposition of calcium carbonate is an exothermic reaction.', a: 2 },
    { A: 'Rancidity is the slow oxidation of metals exposed to moist air.', R: 'Rancidity is the oxidation of fats and oils in food, producing a bad smell and taste.', a: 3 },
    { A: 'Packets of chips are flushed with nitrogen gas before sealing.', R: 'Nitrogen is an unreactive gas that prevents the oxidation (rancidity) of the fats.', a: 0 },
    { A: 'Silver chloride is stored in dark-coloured bottles.', R: 'Silver chloride is a white crystalline solid.', a: 1 },
    { A: 'The reaction of an acid with a base is a double displacement reaction.', R: 'In it, one element displaces another element from its compound.', a: 2 },
    { A: 'All decomposition reactions are exothermic.', R: 'Decomposition reactions generally require energy in the form of heat, light or electricity.', a: 3 },
    { A: 'When copper is heated in air, a black substance is formed.', R: 'Copper reacts with the oxygen of the air to form black copper(II) oxide.', a: 0 },
    { A: 'Brisk effervescence is seen when dilute HCl is added to sodium carbonate.', R: 'Hydrogen gas is evolved, which turns lime water milky.', a: 2 },
    { A: 'Photosynthesis is an endothermic reaction.', R: 'Green plants are found both on land and in water.', a: 1 }
  ]);

  add('vsa', [
    { q: 'Define a chemical reaction.', a: 'A chemical reaction is a process in which one or more substances (reactants) are converted into one or more new substances (products) having different properties.', k: ['reactants → new products', 'different properties'], cm: 'Describing a physical change (no new substance).' },
    { q: 'List any two observations that show a chemical reaction has taken place.', a: 'Any two of: a change in colour, evolution of a gas, a change in temperature, formation of a precipitate, or a change in state/smell.', k: ['colour change / gas / temperature', 'precipitate / state change'], cm: 'Giving “change in shape” (that is physical).' },
    { q: 'What is a balanced chemical equation?', a: 'One in which the number of atoms of each element is equal on both sides of the equation, so that it obeys the law of conservation of mass.', k: ['equal atoms of each element both sides', 'conservation of mass'], cm: 'Confusing it with a word equation.' },
    { q: 'Write the balanced equation for the reaction of hydrogen with oxygen to form water.', a: '2H₂ + O₂ → 2H₂O.', k: ['2H₂ + O₂ → 2H₂O'], cm: 'Leaving H₂ + O₂ → H₂O unbalanced.' },
    { q: 'Balance the equation: Fe + Cl₂ → FeCl₃.', a: '2Fe + 3Cl₂ → 2FeCl₃.', k: ['2Fe + 3Cl₂ → 2FeCl₃'], cm: 'Not balancing the chlorine atoms.' },
    { q: 'Balance the equation: Al + O₂ → Al₂O₃.', a: '4Al + 3O₂ → 2Al₂O₃.', k: ['4Al + 3O₂ → 2Al₂O₃'], cm: 'Changing the formula of Al₂O₃ instead of the coefficients.' },
    { q: 'Balance the equation: Na + H₂O → NaOH + H₂.', a: '2Na + 2H₂O → 2NaOH + H₂.', k: ['2Na + 2H₂O → 2NaOH + H₂'], cm: 'Leaving hydrogen unbalanced.' },
    { q: 'Give one balanced example each of a combination and a decomposition reaction.', a: 'Combination: CaO + H₂O → Ca(OH)₂. Decomposition: 2H₂O →(electricity) 2H₂ + O₂.', k: ['combination: CaO + H₂O → Ca(OH)₂', 'decomposition: 2H₂O → 2H₂ + O₂'], cm: 'Interchanging the two examples.' },
    { q: 'Why are decomposition reactions said to be the opposite of combination reactions?', a: 'In a combination reaction two or more substances join to form a single product, whereas in a decomposition reaction a single compound splits into two or more products — so they are opposite processes.', k: ['combination: many → one', 'decomposition: one → many'], cm: 'Saying both form a single product.' },
    { q: 'What is a precipitation reaction? Give one balanced example.', a: 'A reaction in which two solutions react to form an insoluble solid (precipitate). Example: Na₂SO₄ + BaCl₂ → BaSO₄↓ + 2NaCl.', k: ['forms an insoluble precipitate', 'Na₂SO₄ + BaCl₂ → BaSO₄↓ + 2NaCl'], cm: 'Not showing the precipitate (↓).' },
    { q: 'State what is observed when dilute hydrochloric acid is added to sodium carbonate.', a: 'Brisk effervescence is seen due to the evolution of carbon dioxide gas (which turns lime water milky).', k: ['brisk effervescence', 'CO₂ evolved'], cm: 'Saying hydrogen is evolved.' },
    { q: 'Name the type of reaction: (i) burning of magnesium and (ii) heating of lead nitrate.', a: '(i) Combination reaction; (ii) thermal decomposition reaction.', k: ['(i) combination', '(ii) thermal decomposition'], cm: 'Calling the heating of lead nitrate a combination reaction.' },
    { q: 'What is meant by oxidation in terms of oxygen and hydrogen?', a: 'Oxidation is the addition of oxygen to a substance, or the removal of hydrogen from it.', k: ['addition of oxygen', 'removal of hydrogen'], cm: 'Defining oxidation as loss of oxygen.' },
    { q: 'What is meant by reduction in terms of oxygen and hydrogen?', a: 'Reduction is the removal of oxygen from a substance, or the addition of hydrogen to it.', k: ['removal of oxygen', 'addition of hydrogen'], cm: 'Defining reduction as gain of oxygen.' },
    { q: 'Define a redox reaction.', a: 'A reaction in which oxidation and reduction take place simultaneously — one substance is oxidised while another is reduced.', k: ['oxidation & reduction together', 'one oxidised, one reduced'], cm: 'Saying only oxidation occurs.' },
    { q: 'What is corrosion? Give one example.', a: 'Corrosion is the slow deterioration of a metal by the action of air, moisture or chemicals on its surface, e.g. the rusting of iron.', k: ['slow deterioration of metal', 'e.g. rusting of iron'], cm: 'Confusing corrosion with rancidity.' },
    { q: 'What is rancidity?', a: 'Rancidity is the oxidation of the fats and oils in food when exposed to air, which produces a bad smell and taste.', k: ['oxidation of fats and oils', 'bad smell and taste'], cm: 'Confusing rancidity with corrosion.' },
    { q: 'Give any two methods used to prevent rancidity.', a: 'Any two of: adding antioxidants, flushing packets with nitrogen, using airtight packaging, and refrigeration.', k: ['antioxidants / nitrogen flush', 'airtight / refrigeration'], cm: 'Suggesting adding more oil/fat.' },
    { q: 'Distinguish between exothermic and endothermic reactions in one line each.', a: 'Exothermic reactions release heat to the surroundings; endothermic reactions absorb heat from the surroundings.', k: ['exothermic: heat released', 'endothermic: heat absorbed'], cm: 'Interchanging the two.' },
    { q: 'Why is respiration called an exothermic process?', a: 'Because glucose is oxidised in the cells, releasing energy (heat) that the body uses.', k: ['glucose oxidised', 'energy/heat released'], cm: 'Confusing it with photosynthesis.' },
    { q: 'What is observed when a few drops of silver nitrate solution are added to sodium chloride solution?', a: 'A white precipitate of silver chloride is formed.', k: ['white precipitate', 'silver chloride'], cm: 'Naming a coloured precipitate.' },
    { q: 'Convert into a balanced equation: hydrogen sulphide gas burns in air to form water and sulphur dioxide.', a: '2H₂S + 3O₂ → 2H₂O + 2SO₂.', k: ['2H₂S + 3O₂ → 2H₂O + 2SO₂'], cm: 'Leaving oxygen or sulphur unbalanced.' }
  ]);

  add('sa', [
    { q: 'State the law of conservation of mass and show how it applies to a balanced equation, using CH₄ + 2O₂ → CO₂ + 2H₂O.', a: 'The law states that mass can neither be created nor destroyed in a chemical reaction, so the total mass of the reactants equals that of the products. In CH₄ + 2O₂ → CO₂ + 2H₂O, each side has 1 C, 4 H and 4 O atoms, so mass is conserved — the equation obeys the law.', k: ['mass neither created nor destroyed', 'equal atoms each side', 'C:1, H:4, O:4'], cm: 'Altering formulae instead of coefficients.' },
    { q: 'Balance the equation N₂ + H₂ → NH₃ and name the type of reaction.', a: 'N₂ + 3H₂ → 2NH₃. It is a combination reaction (two elements combine to form a single compound).', k: ['N₂ + 3H₂ → 2NH₃', 'combination reaction'], cm: 'Leaving hydrogen atoms unbalanced.' },
    { q: 'What information does a balanced chemical equation give, and what are two of its limitations?', a: 'It tells us the reactants and products, their relative numbers of molecules/moles, and (with state symbols) their physical states. Limitations: it does not show the speed of the reaction, the conditions (temperature/pressure) unless written on the arrow, whether the reaction is complete, or the heat change unless stated.', k: ['reactants, products, ratios, states', 'no speed / conditions / heat by itself'], cm: 'Saying an equation shows the rate of reaction.' },
    { q: 'Explain the three types of decomposition reactions with one equation each.', a: 'Thermal decomposition (by heat): CaCO₃ →(heat) CaO + CO₂. Electrolytic decomposition (by electricity): 2H₂O →(electricity) 2H₂ + O₂. Photochemical decomposition (by light): 2AgCl →(sunlight) 2Ag + Cl₂.', k: ['thermal (heat)', 'electrolytic (electricity)', 'photochemical (light)'], cm: 'Giving a combination example.' },
    { q: 'Give reasons: (i) the colour of copper sulphate solution changes when an iron nail is dipped in it; (ii) a magnesium ribbon is cleaned before burning.', a: '(i) Iron, being more reactive, displaces copper from copper sulphate; the blue Cu²⁺ is removed and green FeSO₄ forms, so the colour changes from blue to light green. (ii) A layer of magnesium oxide on the ribbon is removed by cleaning so that the metal burns readily and completely.', k: ['iron displaces copper → green FeSO₄', 'MgO layer removed for clean burning'], cm: 'Saying copper displaces iron.' },
    { q: 'Identify the oxidising and reducing agents in (i) 2PbO + C → 2Pb + CO₂ and (ii) CuO + H₂ → Cu + H₂O.', a: '(i) PbO is reduced (loses oxygen), so PbO is the oxidising agent; C is oxidised (gains oxygen), so C is the reducing agent. (ii) CuO is reduced, so it is the oxidising agent; H₂ is oxidised, so it is the reducing agent.', k: ['(i) PbO oxidising, C reducing', '(ii) CuO oxidising, H₂ reducing'], cm: 'Interchanging the oxidising and reducing agents.' },
    { q: 'Distinguish between displacement and double displacement reactions with one example of each.', a: 'In a displacement reaction a more reactive element takes the place of a less reactive one in a compound, e.g. Fe + CuSO₄ → FeSO₄ + Cu. In a double displacement reaction two compounds exchange their ions, often forming a precipitate, e.g. Na₂SO₄ + BaCl₂ → BaSO₄↓ + 2NaCl.', k: ['displacement: one element replaces another', 'double displacement: ions exchanged', 'examples'], cm: 'Not showing an exchange of ions in the double displacement example.' },
    { q: 'Show that ZnO + C → Zn + CO is a redox reaction by identifying the oxidation and the reduction.', a: 'ZnO loses oxygen to become Zn — it is reduced. Carbon gains oxygen to become CO — it is oxidised. Since reduction and oxidation happen together, it is a redox reaction (C is the reducing agent and ZnO the oxidising agent).', k: ['ZnO reduced (loses O)', 'C oxidised (gains O)', 'both together → redox'], cm: 'Saying only one process occurs.' },
    { q: 'Describe the observations and write the equation when zinc granules are added to dilute sulphuric acid.', a: 'The zinc dissolves gradually and colourless bubbles of hydrogen gas are given off; the test tube becomes slightly warm. The gas burns with a “pop” sound. Equation: Zn + H₂SO₄ → ZnSO₄ + H₂.', k: ['bubbles of H₂, zinc dissolves', 'pop sound', 'Zn + H₂SO₄ → ZnSO₄ + H₂'], cm: 'Saying CO₂ is evolved.' },
    { q: 'Explain the rusting of iron: state the conditions required and two methods of prevention.', a: 'Rusting is the corrosion of iron in which it is oxidised by air and moisture to form hydrated iron(III) oxide (rust). Both oxygen (air) and moisture (water) are needed. Prevention (any two): painting or greasing, galvanising (coating with zinc), and making corrosion-resistant alloys such as stainless steel.', k: ['oxidation by air + moisture → rust', 'both O₂ and water needed', 'painting/galvanising/alloying'], cm: 'Giving only one condition for rusting.' },
    { q: 'What is rancidity? Explain why it occurs and how nitrogen flushing prevents it.', a: 'Rancidity is the oxidation of fats and oils in food, giving a bad smell and taste. It occurs because oxygen in the air reacts with the fats. Flushing a packet with unreactive nitrogen displaces the oxygen, so the fats cannot be oxidised and the food stays fresh longer.', k: ['oxidation of fats/oils', 'oxygen causes it', 'nitrogen removes oxygen'], cm: 'Saying nitrogen chemically reacts with the fats.' },
    { q: 'Classify respiration, photosynthesis and the burning of fuels as exothermic or endothermic, giving a reason for each.', a: 'Respiration is exothermic — glucose is oxidised and energy is released. Photosynthesis is endothermic — light energy is absorbed to make glucose. Burning of fuels is exothermic — combustion releases heat and light.', k: ['respiration exothermic', 'photosynthesis endothermic', 'combustion exothermic'], cm: 'Calling photosynthesis exothermic.' },
    { q: 'Balance and identify the type: (i) BaCl₂ + Na₂SO₄ → BaSO₄ + NaCl; (ii) AgCl → Ag + Cl₂.', a: '(i) BaCl₂ + Na₂SO₄ → BaSO₄↓ + 2NaCl — a double displacement (precipitation) reaction. (ii) 2AgCl →(sunlight) 2Ag + Cl₂ — a (photochemical) decomposition reaction.', k: ['(i) double displacement, 2NaCl', '(ii) 2AgCl → 2Ag + Cl₂, decomposition'], cm: 'Not balancing NaCl or Cl₂.' },
    { q: 'Write the balanced equations for the action of heat on (i) ferrous sulphate and (ii) lead nitrate, and name the reaction type.', a: '(i) 2FeSO₄ →(heat) Fe₂O₃ + SO₂ + SO₃. (ii) 2Pb(NO₃)₂ →(heat) 2PbO + 4NO₂ + O₂. Both are thermal decomposition reactions.', k: ['2FeSO₄ → Fe₂O₃ + SO₂ + SO₃', '2Pb(NO₃)₂ → 2PbO + 4NO₂ + O₂', 'thermal decomposition'], cm: 'Leaving the equations unbalanced.' },
    { q: 'A metal X is used in the thermite reaction to join railway tracks. Identify X, write the equation, and name the type of reaction.', a: 'X is aluminium. Fe₂O₃ + 2Al → 2Fe + Al₂O₃ + heat. It is a displacement (and highly exothermic redox) reaction; the heat produces molten iron that welds the rails.', k: ['aluminium', 'Fe₂O₃ + 2Al → 2Fe + Al₂O₃', 'displacement / exothermic redox'], cm: 'Naming a metal less reactive than iron.' },
    { q: 'State the observations and reaction types when (i) quicklime is added to water and (ii) an iron nail is dipped in copper sulphate solution.', a: '(i) Quicklime reacts vigorously with water, giving out heat (the container becomes hot); CaO + H₂O → Ca(OH)₂ — a combination (exothermic) reaction. (ii) The blue colour fades to light green and a brown deposit of copper forms on the nail; Fe + CuSO₄ → FeSO₄ + Cu — a displacement reaction.', k: ['(i) heat released, combination', '(ii) blue → green, brown deposit, displacement'], cm: 'Swapping the two reaction types.' },
    { q: 'Explain why digestion of food and respiration are considered chemical changes.', a: 'In digestion, complex food molecules are broken down into simpler, different substances (like glucose and amino acids), and in respiration glucose is oxidised into carbon dioxide and water with the release of energy. Since new substances with different properties are formed in both, they are chemical changes.', k: ['new substances formed', 'digestion: complex → simple', 'respiration: glucose oxidised'], cm: 'Calling them physical changes.' },
    { q: 'State three differences between physical and chemical changes with one example each.', a: '(i) In a physical change no new substance forms (e.g. melting of ice), while in a chemical change a new substance forms (e.g. burning of paper). (ii) Physical changes are usually easily reversible; chemical changes are usually not. (iii) Physical changes involve little energy change; chemical changes often release or absorb noticeable energy.', k: ['no new substance vs new substance', 'reversible vs usually not', 'energy change'], cm: 'Giving examples that contradict the definitions.' },
    { q: 'Give reasons: (i) silver articles turn black after some time; (ii) copper vessels lose their shine and gain a green coat in moist air.', a: '(i) Silver reacts with hydrogen sulphide present in air to form a black layer of silver sulphide (Ag₂S) — a corrosion. (ii) Copper reacts slowly with moist carbon dioxide in air to form a green layer of basic copper carbonate on its surface.', k: ['silver → black Ag₂S', 'copper → green basic carbonate'], cm: 'Saying silver forms silver oxide.' },
    { q: 'Write the balanced equations for the reaction of (i) sodium and (ii) potassium with water, and state one observation.', a: '(i) 2Na + 2H₂O → 2NaOH + H₂. (ii) 2K + 2H₂O → 2KOH + H₂. Both react vigorously; the reactions are so exothermic that the hydrogen produced often catches fire, and the metal moves about on the water surface.', k: ['2Na + 2H₂O → 2NaOH + H₂', '2K + 2H₂O → 2KOH + H₂', 'vigorous, catches fire'], cm: 'Forgetting the reactions are exothermic and vigorous.' },
    { q: 'How can you show that the reaction of calcium oxide with water is exothermic?', a: 'Take some calcium oxide (quicklime) in a beaker and add a little water; on touching the beaker it feels hot, and a thermometer placed in the mixture shows a rise in temperature. This heat given out proves the reaction CaO + H₂O → Ca(OH)₂ is exothermic.', k: ['beaker becomes hot', 'temperature rises', 'CaO + H₂O → Ca(OH)₂'], cm: 'Saying the mixture becomes cold.' },
    { q: 'What is a skeletal (unbalanced) chemical equation? Convert Fe + H₂O → Fe₃O₄ + H₂ from skeletal to balanced.', a: 'A skeletal equation is one written with correct formulae but without equal numbers of atoms of each element on the two sides (i.e. not yet balanced). Balanced: 3Fe + 4H₂O → Fe₃O₄ + 4H₂.', k: ['unbalanced but correct formulae', '3Fe + 4H₂O → Fe₃O₄ + 4H₂'], cm: 'Balancing hydrogen before oxygen incorrectly.' }
  ]);

  add('ma', [
    { q: 'A student writes “H₂ + O₂ → H₂O” and claims it is balanced. (a) Is it balanced? Why or why not? (b) Balance it correctly. (c) Which law is being satisfied? (d) What must never be changed while balancing?', a: '(a) It is not balanced: the left side has 2 oxygen atoms but the right side has only 1. (b) 2H₂ + O₂ → 2H₂O. (c) The law of conservation of mass. (d) The formulae of the substances (the subscripts) must never be changed — only the coefficients may be adjusted.', k: ['unbalanced: O 2 vs 1', '2H₂ + O₂ → 2H₂O', 'conservation of mass', 'never change subscripts/formulae'], cm: 'Changing H₂O to H₂O₂ to balance oxygen.' },
    { q: 'Name the type of each reaction: (a) CaO + H₂O → Ca(OH)₂; (b) 2FeSO₄ → Fe₂O₃ + SO₂ + SO₃; (c) Fe + CuSO₄ → FeSO₄ + Cu; (d) BaCl₂ + Na₂SO₄ → BaSO₄ + 2NaCl.', a: '(a) Combination reaction. (b) Thermal decomposition reaction. (c) Displacement reaction. (d) Double displacement (precipitation) reaction.', k: ['(a) combination', '(b) thermal decomposition', '(c) displacement', '(d) double displacement'], cm: 'Confusing decomposition with displacement.' },
    { q: 'In the reaction 3MnO₂ + 4Al → 3Mn + 2Al₂O₃: (a) which substance is oxidised? (b) which is reduced? (c) name the reducing agent; (d) name the oxidising agent.', a: '(a) Aluminium is oxidised (it gains oxygen to form Al₂O₃). (b) MnO₂ is reduced (it loses oxygen to give Mn). (c) The reducing agent is aluminium. (d) The oxidising agent is MnO₂.', k: ['Al oxidised', 'MnO₂ reduced', 'reducing agent Al', 'oxidising agent MnO₂'], cm: 'Interchanging oxidised and reduced.' },
    { q: 'An iron gate near the seashore rusts much faster than one inland. (a) Why? (b) State the two conditions needed for rusting. (c) Give two methods to prevent it. (d) Name the substance formed on rusting.', a: '(a) Sea air is moist and salty; the moisture and salts speed up the oxidation of iron, so rusting is faster. (b) Both oxygen (air) and moisture (water) are needed. (c) Painting/greasing and galvanising (or alloying to stainless steel). (d) Hydrated iron(III) oxide (rust), Fe₂O₃·xH₂O.', k: ['salty moist air speeds rusting', 'oxygen + moisture', 'painting/galvanising', 'Fe₂O₃·xH₂O'], cm: 'Giving only one condition for rusting.' },
    { q: 'On mixing solutions of lead nitrate and potassium iodide, a yellow precipitate forms. (a) Write the balanced equation. (b) Name the precipitate. (c) Name the reaction type. (d) What remains dissolved in the solution?', a: '(a) Pb(NO₃)₂ + 2KI → PbI₂↓ + 2KNO₃. (b) The yellow precipitate is lead iodide (PbI₂). (c) It is a double displacement (precipitation) reaction. (d) Potassium nitrate (KNO₃) remains dissolved in the solution.', k: ['Pb(NO₃)₂ + 2KI → PbI₂↓ + 2KNO₃', 'lead iodide (yellow)', 'double displacement', 'KNO₃ in solution'], cm: 'Forgetting to balance KI/KNO₃.' },
    { q: 'Ferrous sulphate crystals are heated strongly in a dry test tube. (a) What colour change is seen? (b) What smell is produced? (c) Which gases are evolved? (d) Name the type of reaction.', a: '(a) The green ferrous sulphate crystals lose water and then turn brownish (reddish-brown Fe₂O₃ forms). (b) A smell of burning sulphur is produced. (c) Sulphur dioxide (SO₂) and sulphur trioxide (SO₃) gases are evolved. (d) It is a thermal decomposition reaction: 2FeSO₄ → Fe₂O₃ + SO₂ + SO₃.', k: ['green → brown', 'smell of burning sulphur', 'SO₂ and SO₃', 'thermal decomposition'], cm: 'Naming carbon dioxide as the gas evolved.' },
    { q: 'Three test tubes show: (i) sodium hydroxide pellets added to water become hot; (ii) ammonium chloride added to water becomes cold; (iii) dilute acid mixed with a base becomes hot. Classify each as exothermic or endothermic and justify.', a: '(i) Exothermic — dissolving NaOH releases heat (the tube warms up). (ii) Endothermic — dissolving ammonium chloride absorbs heat (the tube cools). (iii) Exothermic — neutralisation of an acid by a base releases heat. In each case a rise in temperature indicates an exothermic change and a fall indicates an endothermic one.', k: ['(i) exothermic (warms)', '(ii) endothermic (cools)', '(iii) exothermic (neutralisation)', 'rise/fall in temperature'], cm: 'Calling the cooling of NH₄Cl exothermic.' },
    { q: 'Four metals A, B, C and D are added separately to copper sulphate solution; only A, B and C displace copper. (a) Which metal is the least reactive? (b) Give a reason. (c) Could D be silver or gold? (d) State the general rule involved.', a: '(a) D is the least reactive. (b) Because D cannot displace copper, it must be less reactive than copper, unlike A, B and C. (c) Yes — D could be silver or gold, as both are less reactive than copper. (d) A more reactive metal displaces a less reactive metal from its salt solution.', k: ['D least reactive', 'D less reactive than copper', 'silver/gold possible', 'more reactive displaces less reactive'], cm: 'Calling D the most reactive.' },
    { q: 'A cook is advised to store fried snacks in airtight containers and not to reuse frying oil many times. (a) Which chemical process is being avoided? (b) Why do airtight containers help? (c) Why is repeatedly heated oil harmful? (d) Suggest one substance added by manufacturers to prevent this.', a: '(a) Rancidity (the oxidation of fats and oils). (b) Airtight containers keep out oxygen, so the fats are not oxidised and the snacks stay fresh. (c) Repeated heating speeds up oxidation and produces harmful products, making the oil rancid and unhealthy. (d) Antioxidants are added to prevent rancidity.', k: ['rancidity', 'airtight keeps out oxygen', 'reheating speeds oxidation', 'antioxidants'], cm: 'Calling the process corrosion.' },
    { q: 'Consider the reaction Zn + HCl → ZnCl₂ + H₂. (a) Write the balanced equation with state symbols. (b) How would you test the gas evolved? (c) Name the reaction type. (d) What does a single forward arrow indicate?', a: '(a) Zn(s) + 2HCl(aq) → ZnCl₂(aq) + H₂(g). (b) Bring a burning splint near the gas; it burns with a “pop” sound, confirming hydrogen. (c) It is a displacement reaction. (d) A single forward arrow shows the direction of the reaction — reactants change into products.', k: ['Zn(s) + 2HCl(aq) → ZnCl₂(aq) + H₂(g)', 'pop test for hydrogen', 'displacement', 'arrow shows reaction direction'], cm: 'Forgetting the coefficient 2 for HCl.' },
    { q: 'Silver chloride is a white solid that is stored in dark bottles. (a) Why are dark bottles used? (b) Write the reaction that occurs in sunlight. (c) What colour change is seen? (d) State one application of this reaction.', a: '(a) Silver chloride decomposes in sunlight, so dark bottles keep the light out. (b) 2AgCl →(sunlight) 2Ag + Cl₂. (c) The white AgCl turns grey (as silver metal forms). (d) It is used in black-and-white photography.', k: ['decomposes in light', '2AgCl → 2Ag + Cl₂', 'white → grey', 'photography'], cm: 'Calling it a combination reaction.' },
    { q: 'Railway workers weld broken rails using a strongly exothermic reaction. (a) Name the reactants. (b) Write the balanced equation. (c) Why does molten iron form? (d) Give all the reaction types this reaction belongs to.', a: '(a) Iron(III) oxide and aluminium powder. (b) Fe₂O₃ + 2Al → 2Fe + Al₂O₃ + heat. (c) The reaction releases so much heat that the iron produced melts and flows into the gap to weld the rails. (d) It is a displacement reaction, a redox reaction and an exothermic reaction.', k: ['Fe₂O₃ + Al', 'Fe₂O₃ + 2Al → 2Fe + Al₂O₃', 'heat melts the iron', 'displacement + redox + exothermic'], cm: 'Missing that it releases heat.' },
    { q: 'Consider the neutralisation NaOH + HCl → NaCl + H₂O. (a) Name the products. (b) Why is it a double displacement reaction? (c) Is it exothermic or endothermic? (d) How could you show the temperature change?', a: '(a) Sodium chloride (salt) and water. (b) It is a double displacement reaction because the ions are exchanged — Na⁺ pairs with Cl⁻ and H⁺ with OH⁻. (c) It is exothermic. (d) Place a thermometer in the acid and add the base; a rise in temperature during mixing shows the reaction gives out heat.', k: ['NaCl + H₂O', 'ions exchanged', 'exothermic', 'thermometer shows rise'], cm: 'Calling it a displacement (single) reaction.' },
    { q: 'Four processes are given: melting of wax, burning of a candle wick, rusting of a nail, and dissolving sugar in water. (a) Classify each as physical or chemical. (b) In which do new substances form? (c) Which are easily reversible? (d) Give one reason for your classification of rusting.', a: '(a) Melting of wax — physical; burning of the wick — chemical; rusting — chemical; dissolving sugar — physical. (b) New substances form in the burning of the wick and in rusting. (c) Melting of wax and dissolving sugar are easily reversible. (d) Rusting is chemical because a new substance, hydrated iron(III) oxide (rust), with different properties is formed.', k: ['melting/dissolving physical; burning/rusting chemical', 'new substances: burning & rusting', 'melting & dissolving reversible', 'rust is a new substance'], cm: 'Calling rusting a physical change.' }
  ]);

  add('la', [
    { q: 'Explain, step by step, how to balance a chemical equation, using Fe + H₂O → Fe₃O₄ + H₂ as an example, and state the law it obeys.', a: 'Balancing makes the number of atoms of each element equal on both sides. Steps: (1) Write the skeletal equation: Fe + H₂O → Fe₃O₄ + H₂. (2) Balance the atom occurring in the most complex formula first — oxygen: there are 4 O in Fe₃O₄, so put 4 before H₂O. (3) This gives 8 H on the left, so put 4 before H₂ on the right. (4) Balance iron: 3 Fe in Fe₃O₄, so put 3 before Fe. Final: 3Fe + 4H₂O → Fe₃O₄ + 4H₂. Check: Fe 3=3, H 8=8, O 4=4. Only coefficients were changed, never the formulae. This obeys the law of conservation of mass — matter is neither created nor destroyed, atoms are only rearranged.', k: ['balance most complex first (O)', '3Fe + 4H₂O → Fe₃O₄ + 4H₂', 'check all atoms', 'conservation of mass'], cm: 'Changing formulae (subscripts) instead of coefficients.' },
    { q: 'Describe the four main types of chemical reactions — combination, decomposition, displacement and double displacement — giving two balanced examples of each.', a: 'Combination (two or more substances form one product): CaO + H₂O → Ca(OH)₂; 2H₂ + O₂ → 2H₂O. Decomposition (one compound splits into two or more): CaCO₃ →(heat) CaO + CO₂; 2H₂O →(electricity) 2H₂ + O₂. Displacement (a more reactive element replaces a less reactive one): Fe + CuSO₄ → FeSO₄ + Cu; Zn + 2HCl → ZnCl₂ + H₂. Double displacement (ions are exchanged, often a precipitate forms): Na₂SO₄ + BaCl₂ → BaSO₄↓ + 2NaCl; AgNO₃ + NaCl → AgCl↓ + NaNO₃.', k: ['combination — two examples', 'decomposition — two examples', 'displacement — two examples', 'double displacement — two examples'], cm: 'Mixing up decomposition and displacement examples.' },
    { q: 'Explain thermal, electrolytic and photochemical decomposition, giving one equation, one observation and one use of each.', a: 'Thermal decomposition uses heat: CaCO₃ →(heat) CaO + CO₂; on heating limestone a gas that turns lime water milky is given off; used to make quicklime. Electrolytic decomposition uses electricity: 2H₂O →(electricity) 2H₂ + O₂; two gases collect over the electrodes in a 2:1 volume ratio; used to obtain hydrogen and oxygen. Photochemical decomposition uses light: 2AgCl →(sunlight) 2Ag + Cl₂; white silver chloride turns grey in sunlight; used in black-and-white photography.', k: ['thermal: CaCO₃, quicklime', 'electrolytic: water, 2:1 gases', 'photochemical: AgCl, photography'], cm: 'Using a combination example for decomposition.' },
    { q: 'Explain oxidation, reduction, oxidising agents and reducing agents, identify them in CuO + H₂ → Cu + H₂O, and give two effects of oxidation in daily life.', a: 'Oxidation is the addition of oxygen (or loss of hydrogen/electrons); reduction is the loss of oxygen (or gain of hydrogen/electrons). An oxidising agent supplies oxygen (or removes hydrogen) and is itself reduced; a reducing agent removes oxygen (or supplies hydrogen) and is itself oxidised. In CuO + H₂ → Cu + H₂O, CuO loses oxygen (reduced, so it is the oxidising agent) and H₂ gains oxygen (oxidised, so it is the reducing agent). Two daily-life effects of oxidation: (i) corrosion of metals, such as the rusting of iron, and (ii) rancidity of fats and oils in food.', k: ['oxidation/reduction defined', 'CuO = oxidising agent', 'H₂ = reducing agent', 'corrosion & rancidity'], cm: 'Interchanging the oxidising and reducing agents.' },
    { q: 'Discuss oxidation in everyday life by describing the corrosion of iron, silver and copper, and the rancidity of food, with one method of prevention for each.', a: 'Corrosion is the slow oxidation of metals by their surroundings. Iron rusts in the presence of air and moisture, forming reddish-brown hydrated iron(III) oxide — prevented by painting or galvanising. Silver reacts with hydrogen sulphide in air to form a black coating of silver sulphide — prevented by keeping it clean/coated and away from such gases. Copper reacts with moist air to form a green layer of basic copper carbonate — prevented by keeping it dry and polished. Rancidity is the oxidation of fats and oils in food, giving a bad smell and taste — prevented by adding antioxidants, flushing packets with nitrogen, or refrigeration.', k: ['iron → rust (paint/galvanise)', 'silver → black Ag₂S', 'copper → green carbonate', 'rancidity (antioxidants/N₂)'], cm: 'Giving the same product for all three metals.' },
    { q: 'Define exothermic and endothermic reactions and classify, with reasons, respiration, photosynthesis, combustion of fuels, decomposition of vegetable matter and the reaction of quicklime with water.', a: 'Exothermic reactions give out heat to the surroundings; endothermic reactions absorb heat. Respiration — exothermic (glucose is oxidised, releasing energy). Photosynthesis — endothermic (light energy is absorbed to make glucose). Combustion of fuels — exothermic (burning releases heat and light). Decomposition of vegetable matter into compost — exothermic (heat is given out, so a compost heap feels warm). Reaction of quicklime with water — exothermic (the mixture becomes hot).', k: ['exo gives out / endo absorbs heat', 'respiration & combustion exo', 'photosynthesis endo', 'compost & quicklime exo'], cm: 'Calling photosynthesis exothermic or compost formation endothermic.' },
    { q: 'Explain displacement reactions and the reactivity series, describing an experiment with metals in salt solutions and giving suitable equations.', a: 'A displacement reaction is one in which a more reactive metal displaces a less reactive metal from its salt solution. The reactivity series arranges metals in decreasing order of reactivity. Experiment: place iron nails in copper sulphate solution and copper wire in iron sulphate solution. In the first, the blue colour fades and a brown copper coating forms — iron displaces copper: Fe + CuSO₄ → FeSO₄ + Cu; in the second, nothing happens because copper is less reactive than iron. Similarly Zn + CuSO₄ → ZnSO₄ + Cu shows zinc is more reactive than copper. Such experiments let us arrange metals in order of reactivity.', k: ['more reactive displaces less reactive', 'reactivity series', 'Fe + CuSO₄ → FeSO₄ + Cu (blue fades)', 'copper cannot displace iron'], cm: 'Expecting copper to displace iron.' },
    { q: 'Explain double displacement and precipitation reactions, describing how an insoluble salt is prepared, with the ionic idea and two examples.', a: 'In a double displacement reaction two compounds in solution exchange their ions. When one of the new products is insoluble, it separates as a solid precipitate — a precipitation reaction. To prepare an insoluble salt, two soluble salts containing the required ions are mixed: for example, mixing barium chloride and sodium sulphate gives insoluble barium sulphate: BaCl₂ + Na₂SO₄ → BaSO₄↓ + 2NaCl. Here Ba²⁺ combines with SO₄²⁻ to form the precipitate, while Na⁺ and Cl⁻ stay in solution. Another example: AgNO₃ + NaCl → AgCl↓ + NaNO₃, where a white precipitate of silver chloride forms. The precipitate is separated by filtration.', k: ['ions exchanged', 'insoluble product = precipitate', 'BaCl₂ + Na₂SO₄ → BaSO₄↓ + 2NaCl', 'AgNO₃ + NaCl → AgCl↓ + NaNO₃'], cm: 'Saying no ion exchange occurs.' },
    { q: 'For each of these activities, state the main observation, the balanced equation and the reaction type: (i) burning magnesium ribbon; (ii) heating ferrous sulphate; (iii) heating lead nitrate; (iv) iron nail in copper sulphate; (v) barium chloride with sodium sulphate.', a: '(i) Magnesium burns with a dazzling white flame leaving a white ash: 2Mg + O₂ → 2MgO — combination. (ii) Green crystals turn brown and a smell of burning sulphur is given off: 2FeSO₄ → Fe₂O₃ + SO₂ + SO₃ — thermal decomposition. (iii) Brown fumes are evolved: 2Pb(NO₃)₂ → 2PbO + 4NO₂ + O₂ — thermal decomposition. (iv) Blue colour fades to green and a brown deposit forms: Fe + CuSO₄ → FeSO₄ + Cu — displacement. (v) A white precipitate forms: BaCl₂ + Na₂SO₄ → BaSO₄↓ + 2NaCl — double displacement.', k: ['Mg: white flame, combination', 'FeSO₄: brown, decomposition', 'Pb(NO₃)₂: brown fumes, decomposition', 'Fe/CuSO₄ displacement; BaCl₂/Na₂SO₄ double displacement'], cm: 'Mismatching an observation with the wrong reaction.' },
    { q: 'Distinguish between physical and chemical changes and list, with examples, the signs that indicate a chemical reaction has taken place.', a: 'A physical change alters only the physical state or appearance of a substance with no new substance formed and is usually easily reversible (e.g. melting of ice, dissolving of salt). A chemical change forms one or more new substances with different properties and is usually not easily reversible (e.g. burning of paper, rusting of iron). The signs that a chemical reaction has occurred include: a change in colour (e.g. iron nail in copper sulphate), the evolution of a gas (zinc with acid), a change in temperature (quicklime with water), the formation of a precipitate (barium chloride with sodium sulphate), and a change in state or smell.', k: ['physical: no new substance, reversible', 'chemical: new substance formed', 'signs: colour/gas/temperature/precipitate', 'examples for each sign'], cm: 'Listing “change in shape” as a sign of a chemical reaction.' },
    { q: 'Discuss the importance of chemical reactions in everyday life, with at least five examples and the type or effect of each.', a: 'Chemical reactions are central to daily life: (i) Respiration — glucose is oxidised in our cells to release energy (exothermic). (ii) Cooking of food — heat brings about chemical changes that make food digestible. (iii) Digestion — food is broken down into simpler absorbable substances (decomposition). (iv) Burning of fuels — combustion releases heat and light for cooking, transport and electricity. (v) Photosynthesis — green plants make food and release oxygen (endothermic). (vi) Rusting of iron — an unwanted oxidation that damages objects. Understanding these reactions helps us use useful ones and prevent harmful ones like rusting and rancidity.', k: ['respiration', 'cooking/digestion', 'burning of fuels', 'photosynthesis; rusting'], cm: 'Listing only one or two examples.' },
    { q: 'Balance the following equations and classify each: (i) H₂ + N₂ → NH₃; (ii) Pb + CuCl₂ → PbCl₂ + Cu; (iii) KClO₃ → KCl + O₂; (iv) AgNO₃ + NaCl → AgCl + NaNO₃.', a: '(i) N₂ + 3H₂ → 2NH₃ — combination reaction. (ii) Pb + CuCl₂ → PbCl₂ + Cu — displacement reaction (lead is more reactive than copper). (iii) 2KClO₃ →(heat) 2KCl + 3O₂ — thermal decomposition reaction. (iv) AgNO₃ + NaCl → AgCl↓ + NaNO₃ — double displacement (precipitation) reaction.', k: ['N₂ + 3H₂ → 2NH₃ combination', 'Pb + CuCl₂ → PbCl₂ + Cu displacement', '2KClO₃ → 2KCl + 3O₂ decomposition', 'AgNO₃ + NaCl → AgCl↓ + NaNO₃ double displacement'], cm: 'Leaving any of the equations unbalanced.' }
  ]);

  add('cs', [
    { p: 'Not every change we see is a chemical change. When ice melts or sugar dissolves in water, no new substance is formed and the change can be reversed — these are physical changes. But when a nail rusts, a candle burns or milk turns sour, new substances with new properties appear, and the change cannot easily be reversed. Scientists look for tell-tale signs of a chemical reaction, such as a change in colour, the evolution of a gas, a change in temperature, or the formation of an insoluble precipitate.',
      q: [
        { q: 'Give one example each of a physical and a chemical change from the passage.', a: 'Physical change: melting of ice (or dissolving of sugar). Chemical change: rusting of a nail (or burning of a candle / milk turning sour).', m: 2, k: ['physical: melting ice/dissolving sugar', 'chemical: rusting/burning'] },
        { q: 'State any three signs that show a chemical reaction has taken place, with an example of each.', a: 'Three signs: (i) change in colour — e.g. an iron nail turning a blue copper sulphate solution green; (ii) evolution of a gas — e.g. zinc reacting with acid to give hydrogen; (iii) formation of a precipitate — e.g. barium chloride with sodium sulphate giving white barium sulphate. (A change in temperature, as when quicklime reacts with water, is also a sign.)', m: 3, k: ['colour change', 'gas evolution', 'precipitate (or temperature change)'], cm: 'Listing “change in shape” as a sign.' }
      ] },
    { p: 'A chemical equation is a short way of describing a chemical reaction using formulae. But a correct equation must also be balanced — it must have the same number of atoms of each element on both sides. This follows from the law of conservation of mass, which says that matter is neither created nor destroyed in a chemical reaction; the atoms are only rearranged. While balancing, we may change only the coefficients (the numbers before the formulae) and never the formulae themselves.',
      q: [
        { q: 'Why must a chemical equation be balanced?', a: 'Because atoms are only rearranged in a reaction, not created or destroyed; a balanced equation has equal numbers of atoms of each element on both sides, so it obeys the law of conservation of mass.', m: 2, k: ['atoms rearranged, not created/destroyed', 'equal atoms → conservation of mass'] },
        { q: 'Balance the equation Al + O₂ → Al₂O₃, and state what you are and are not allowed to change while balancing.', a: 'Balanced: 4Al + 3O₂ → 2Al₂O₃ (Al: 4 = 4, O: 6 = 6). While balancing we may change only the coefficients (the numbers written before the formulae); we must never change the formulae (subscripts), because that would change the substances themselves.', m: 3, k: ['4Al + 3O₂ → 2Al₂O₃', 'change coefficients only', 'never change formulae'], cm: 'Changing Al₂O₃ to AlO₃ to balance.' }
      ] },
    { p: 'When electricity is passed through acidified water, it splits into hydrogen and oxygen — a decomposition reaction driven by electricity. Similar break-ups can be caused by heat (as when limestone is heated to give lime) or by light (as when silver salts darken in sunlight, the basis of old photography). In every decomposition reaction a single compound is broken down into two or more simpler substances, and energy — heat, light or electricity — must usually be supplied.',
      q: [
        { q: 'What is a decomposition reaction, and what three forms of energy can bring it about?', a: 'A decomposition reaction is one in which a single compound breaks down into two or more simpler substances. It can be brought about by heat (thermal), electricity (electrolytic) or light (photochemical).', m: 2, k: ['single compound → simpler substances', 'heat / electricity / light'] },
        { q: 'Write balanced equations for the decomposition of water by electricity and of limestone by heat, and give one use of each.', a: 'Electrolysis of water: 2H₂O →(electricity) 2H₂ + O₂ — used to obtain hydrogen and oxygen gases. Heating of limestone: CaCO₃ →(heat) CaO + CO₂ — used to manufacture quicklime (calcium oxide) for cement and other industries.', m: 3, k: ['2H₂O → 2H₂ + O₂', 'CaCO₃ → CaO + CO₂', 'uses: gases / quicklime'], cm: 'Writing combination equations instead.' }
      ] },
    { p: 'Many useful metals are obtained by displacement and redox reactions. In the thermite reaction, aluminium — a reactive metal — reduces iron(III) oxide to iron, releasing so much heat that the iron comes out molten and is used to weld railway tracks. Reactions in which one substance is oxidised while another is reduced are called redox reactions, and they are the basis of extracting many metals from their ores.',
      q: [
        { q: 'In the thermite reaction, which substance is oxidised and which is reduced?', a: 'Aluminium is oxidised (it gains oxygen to form Al₂O₃) and iron(III) oxide is reduced (it loses oxygen to give iron).', m: 2, k: ['Al oxidised', 'Fe₂O₃ reduced'] },
        { q: 'Write the balanced equation for the thermite reaction and explain why the iron formed is molten and how this is useful.', a: 'Fe₂O₃ + 2Al → 2Fe + Al₂O₃ + heat. The reaction is highly exothermic, releasing so much heat that the iron produced melts; this molten iron flows into the gap between broken railway tracks and, on solidifying, welds them together.', m: 3, k: ['Fe₂O₃ + 2Al → 2Fe + Al₂O₃', 'highly exothermic → molten iron', 'welds rails'], cm: 'Forgetting that heat is released.' }
      ] },
    { p: 'Metals slowly react with substances in their surroundings and get damaged — a process called corrosion. Iron rusts to a flaky reddish-brown layer in damp air, silver develops a black tarnish, and copper turns green over time. Corrosion wastes huge amounts of metal every year, so it is prevented by painting, oiling, galvanising and by making corrosion-resistant alloys.',
      q: [
        { q: 'Name the coloured substances formed when iron, silver and copper corrode.', a: 'Iron forms reddish-brown rust (hydrated iron(III) oxide); silver forms a black coating of silver sulphide; and copper forms a green coating of basic copper carbonate.', m: 2, k: ['iron → reddish-brown rust', 'silver → black Ag₂S', 'copper → green carbonate'] },
        { q: 'State the two conditions needed for iron to rust and give two methods to prevent rusting, with a reason for one.', a: 'Iron rusts only when both oxygen (air) and moisture (water) are present. It can be prevented by (i) painting or greasing, which forms a barrier that keeps out air and moisture, and (ii) galvanising — coating with zinc, which being more reactive corrodes in preference to the iron (sacrificial protection).', m: 3, k: ['oxygen + moisture needed', 'painting = barrier', 'galvanising = zinc protects (sacrificial)'], cm: 'Giving only one condition for rusting.' }
      ] },
    { p: 'Fried and oily foods do not stay fresh for long. On exposure to air, the fats and oils in them are slowly oxidised, developing an unpleasant smell and taste. This spoiling is called rancidity. To keep such foods fresh, manufacturers add antioxidants, pack the food in airtight containers, flush the packets with unreactive nitrogen gas, or store the food at low temperatures.',
      q: [
        { q: 'What is rancidity, and what causes it?', a: 'Rancidity is the spoiling of fatty/oily foods in which the fats and oils are oxidised on exposure to air, giving a bad smell and taste. It is caused by the oxygen of the air reacting with the fats.', m: 2, k: ['oxidation of fats/oils', 'caused by oxygen in air'] },
        { q: 'Explain how flushing with nitrogen and refrigeration each help to prevent rancidity.', a: 'Flushing a packet with nitrogen replaces the oxygen inside with an unreactive gas, so the fats cannot be oxidised. Refrigeration lowers the temperature, which slows down the rate of the oxidation reaction, so the food stays fresh for longer.', m: 3, k: ['nitrogen removes/replaces oxygen', 'refrigeration slows oxidation', 'both delay rancidity'], cm: 'Saying nitrogen reacts with the fats to protect them.' }
      ] },
    { p: 'Every chemical reaction is accompanied by an energy change. In exothermic reactions heat is given out, so the surroundings get warmer — as when quicklime is added to water, when fuels burn, or during respiration in our bodies. In endothermic reactions heat is taken in, so the surroundings get cooler — as when certain salts dissolve, or when green plants carry out photosynthesis using the energy of sunlight.',
      q: [
        { q: 'Define exothermic and endothermic reactions.', a: 'An exothermic reaction is one that releases heat to the surroundings (they become warmer); an endothermic reaction is one that absorbs heat from the surroundings (they become cooler).', m: 2, k: ['exothermic: heat released', 'endothermic: heat absorbed'] },
        { q: 'Classify respiration, the burning of fuel, photosynthesis and the reaction of quicklime with water as exothermic or endothermic, with a reason for each.', a: 'Respiration is exothermic (glucose is oxidised, releasing energy). Burning of fuel is exothermic (combustion gives out heat and light). Photosynthesis is endothermic (light energy is absorbed to make glucose). The reaction of quicklime with water is exothermic (the mixture becomes hot).', m: 3, k: ['respiration & burning exothermic', 'photosynthesis endothermic', 'quicklime + water exothermic'], cm: 'Calling photosynthesis exothermic.' }
      ] }
  ]);
})();
